use vstd::prelude::*;

verus! {

spec fn prefix_sum_spec(k: int) -> int {
    if k <= 0 {
        0
    } else if k % 2 == 0 {
        k / 2
    } else {
        -((k + 1) / 2)
    }
}

fn solve(queries: Vec<(i8, i8)>) -> (out: Vec<i8>)
    ensures
        out@.len() == queries@.len(),
        forall|i: int|
            0 <= i < queries@.len() ==>
                out@[i] as int
                == prefix_sum_spec((queries@[i].1 as int))
                   - prefix_sum_spec((queries@[i].0 as int) - 1),
{
    fn prefix_sum(k: i16) -> i16 {
        if k <= 0 {
            return 0;
        }
        if k % 2 == 0 {
            k / 2
        } else {
            -(k + 1) / 2
        }
    }

    queries
        .into_iter()
        .map(|(l, r)| {
            let l = l as i16;
            let r = r as i16;

            // Link the executable helper to the spec.
            assert(prefix_sum(r) as int == prefix_sum_spec(r as int));
            assert(prefix_sum(l - 1) as int == prefix_sum_spec((l - 1) as int));

            let ans = prefix_sum(r) - prefix_sum(l - 1);

            // Needed so the cast `ans as i8` matches `as int` in the postcondition.
            // (Verus typically needs a range fact to relate truncating casts.)
            assert(-128i16 <= ans && ans <= 127i16);

            ans as i8
        })
        .collect()
}

} // verus!

